		    {

		    %THIS%="ERREUR: Début de Journée déjà lancé, Réception non autorisée. ";

	     	}

		}

	}

OnUpdate.Result:


				   	if(Integer.parseInt(%EtatSystem%)== 1)

					{

					  	%THIS%="ERREUR: Accée refusé, une procédure est en cours d'execution. ";

					} else	

					{

					    if(Integer.parseInt(%Niveau%) == 1)

						{

