					 	    {

						    %THIS%="ERREUR: Début de Journée déjà lancé, Réception non autorisée. ";

					     	} else

							  {

  				                %EtatSystem%=1;

                                File Filedavb = new File("/opt/apache-tomcat/webapps/TESTDAV/Etat/davb"); 

                                Filedavb.delete(); 

							  }

						}

					}



           if (%THIS02%.equals("0"))

           {

             %THIS%="Confirmation: Nb. Opération recus davb : "+(Integer.parseInt(%THIS01%)+Integer.parseInt(%THIS02%))+" <br> Nb. Opération rejetées davb : "+%THIS02%+" <br> ";

             %EtatSystem%="0";	

			 %Niveau%="1";



           } else

