             %THIS%="Confirmation: Nb. Opération recus davb : "+(Integer.parseInt(%THIS01%)+Integer.parseInt(%THIS02%))+" <br> Nb. Opération rejetées davb : <span style='color:#CC0000'>"+%THIS02%+"</span>";

